-- =============================================================================
-- Migration: 010_listening_sections
-- Feature: IELTS roadmap — Phase I11 (đề Listening do AI tạo)
-- Plan: IELTS Listening + Writing & Speaking (phase I11)
-- Description:
--   One row per Listening part generated by the generateListeningSection op.
--   `section` holds the part in the app's ListeningSection shape (script,
--   speakers, question groups, answers, evidence), already checked by the op
--   and again by the app before it is saved. Each learner sees only their own.
--
-- Safe to re-run. Before it is applied, generating still works for the
-- current visit; the part is just not kept after a reload.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS public.listening_sections (
    id          UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID         NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    part        SMALLINT     NOT NULL CHECK (part BETWEEN 1 AND 4),
    topic       TEXT,
    difficulty  TEXT         NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard')),
    section     JSONB        NOT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_listening_sections_user_time ON public.listening_sections (user_id, created_at DESC);

ALTER TABLE public.listening_sections ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "listening_sections_select_own" ON public.listening_sections;
CREATE POLICY "listening_sections_select_own" ON public.listening_sections
    FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "listening_sections_insert_own" ON public.listening_sections;
CREATE POLICY "listening_sections_insert_own" ON public.listening_sections
    FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "listening_sections_delete_own" ON public.listening_sections;
CREATE POLICY "listening_sections_delete_own" ON public.listening_sections
    FOR DELETE USING (auth.uid() = user_id);
